'use client';
import {useEffect,useMemo,useRef,useState} from 'react';
import Image from 'next/image';
import {BedDouble,CalendarDays,UsersRound,MapPin,Star,Search,Upload,X,Plus,Minus,ChevronDown,ChevronLeft,ChevronRight,SlidersHorizontal,LayoutGrid,List,FileText,Check,AlertCircle,Utensils,ArrowUpRight,LoaderCircle,History,Image as ImageIcon,ShieldCheck,Building2,RefreshCw} from 'lucide-react';
import {blankHotel,uid,nights,validDate,listedRates,listedStay,quoteStay,checkedForPricing,type Hotel,type Contract,type Rate,type Meal,type HotelQuote,type StaySearch} from '@/lib/hotels/model';
import {useModal} from '../use-modal';import {MediaLibrary} from '../media-library';
import type {Proposal} from '@/lib/model';import './hotels.css';
import ContractViewer from './ContractViewer';
import {hotelPhoto,officialHotelPhoto} from '@/lib/hotels/photos';
type Guests={adults:number;ages:(number|null)[]};
type Data={hotels:Hotel[];contracts:Contract[];aiReady:boolean};
const currency=(n:number|null,c='USD')=>n===null?'0':!c?new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n)+' · currency unconfirmed':new Intl.NumberFormat('en-US',{style:'currency',currency:c||'USD',maximumFractionDigits:2}).format(n);
const iso=(d:Date)=>d.toISOString().slice(0,10);const display=(s:string)=>!validDate(s)?'Choose date':new Date(s+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
export default function Hotels({onProposal,onSignIn,onDirty}:{onProposal:(p:Proposal)=>void;onSignIn:()=>void;onDirty:(dirty:boolean)=>void}){
 const [data,setData]=useState<Data>({hotels:[],contracts:[],aiReady:false}),[loading,setLoading]=useState(true),[error,setError]=useState(''),[notice,setNotice]=useState(''),[setup,setSetup]=useState(false),[mode,setMode]=useState<'hotels'|'contracts'>('hotels');
 const [place,setPlace]=useState(''),[from,setFrom]=useState(iso(new Date(Date.now()+86400000))),[to,setTo]=useState(iso(new Date(Date.now()+3*86400000))),[rooms,setRooms]=useState<Guests[]>([{adults:2,ages:[]}]),[plan,setPlan]=useState('HB'),[bookingDate,setBookingDate]=useState(iso(new Date()));
 const [criteria,setCriteria]=useState<StaySearch|null>(null),[calendar,setCalendar]=useState(false),[dateStep,setDateStep]=useState<'from'|'to'>('from'),[month,setMonth]=useState(new Date().getMonth()),[year,setYear]=useState(new Date().getFullYear()),[guests,setGuests]=useState(false),[filters,setFilters]=useState(false),[stars,setStars]=useState<number[]>([]),[hotelText,setHotelText]=useState(''),[roomFilter,setRoomFilter]=useState(''),[missing,setMissing]=useState(true),[budget,setBudget]=useState(''),[sort,setSort]=useState('name'),[grid,setGrid]=useState(false);
 const [uploadOpen,setUploadOpen]=useState(false),[uploadHotel,setUploadHotel]=useState(''),[uploading,setUploading]=useState(false),[progress,setProgress]=useState('');const file=useRef<HTMLInputElement>(null);
 const [draft,setDraft]=useState<Contract|null>(null),[hotel,setHotel]=useState<Hotel|null>(null),[reviewTab,setReviewTab]=useState('Rates'),[dirty,setDirty]=useState(false),[saving,setSaving]=useState(false),[photo,setPhoto]=useState(false),[history,setHistory]=useState<any[]|null>(null);
 const [detail,setDetail]=useState<{hotel:Hotel;quote:HotelQuote;roomType:string}|null>(null),[detailTab,setDetailTab]=useState('Rooms'),[selectedRoom,setSelectedRoom]=useState(''),[proposals,setProposals]=useState<Proposal[]>([]),[proposalId,setProposalId]=useState(''),[adding,setAdding]=useState(false);
 const [ratePage,setRatePage]=useState(0);const [confirmAction,setConfirmAction]=useState<string|null>(null);const reviewForm=useRef<HTMLFormElement>(null);const isOpen=!!draft||!!detail||calendar||guests||uploadOpen||filters;
 function discardReview(){setDraft(null);setHotel(null);setDirty(false);setPhoto(false);setHistory(null);setConfirmAction(null);}
 function closeReview(){if(dirty){setConfirmAction('close');return;}discardReview();}
 useModal(confirmAction!==null,()=>setConfirmAction(null));
 useModal(isOpen,()=>{if(saving||uploading||adding)return;if(confirmAction){setConfirmAction(null);return;}if(photo)setPhoto(false);else if(calendar)setCalendar(false);else if(guests)setGuests(false);else if(filters)setFilters(false);else if(uploadOpen)setUploadOpen(false);else if(detail)setDetail(null);else closeReview();});
 useEffect(()=>{onDirty(dirty||uploading);return()=>onDirty(false)},[dirty,uploading,onDirty]);
 async function request(path='',init?:RequestInit){const r=await fetch('/api/hotels'+(path?'/'+path:''),{...init,signal:AbortSignal.timeout(path.includes('/extract')?115000:45000)});if(r.status===401){onSignIn();throw Error('Please sign in.');}const d=await r.json().catch(()=>({}));if(!r.ok){if(d.setupRequired)setSetup(true);throw Error(d.error||'Could not complete that action. Please try again.');}return d;}
 async function refresh(){setLoading(true);setError('');try{const d=await request();setData(d);setSetup(false);}catch(e){setError((e as Error).message);}finally{setLoading(false);}}
 useEffect(()=>{void refresh()},[]);
 async function openReview(id:string){setError('');try{const c:Contract=await request('contract/'+id);setDraft(c);setHotel(data.hotels.find(h=>h.id===c.hotelId)||null);setReviewTab('Rates');setRatePage(0);setDirty(false);setHistory(null);}catch(e){setError((e as Error).message);}}
 function patch<K extends keyof Contract>(k:K,v:Contract[K]){setDraft(old=>old?{...old,[k]:v,status:k==='status'?v as Contract['status']:'Draft'}:old);setDirty(true);}
 function patchRate(id:string,k:keyof Rate,v:any){if(draft)patch('rates',draft.rates.map(r=>r.id===id?{...r,[k]:v,checked:k==='checked'?v:false}:r));}
 async function saveReview(){if(!draft||!hotel||!reviewForm.current?.reportValidity())return;setSaving(true);setError('');try{const h=await request('save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:'hotel',record:hotel})});setHotel(h);const c=await request('save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({kind:'contract',record:draft})});setDraft(c);setDirty(false);setNotice('Hotel details saved.');await refresh();}catch(e){setError((e as Error).message);}finally{setSaving(false);}}
 async function upload(files:File[]){setUploading(true);setError('');let count=0,duplicates=0;const failures:string[]=[];for(const f of files){try{setProgress(`Reading ${count+1} of ${files.length} · ${f.name}`);const body=new FormData();body.set('file',f);body.set('hotelId',uploadHotel);const result=await request('upload',{method:'POST',body});if(result.duplicate)duplicates++;else await request('contract/'+result.contract.id+'/extract',{method:'POST'});}catch(e){failures.push(f.name+': '+(e as Error).message);}count++;}setProgress(`${count} files checked · ${duplicates} duplicates skipped`);setUploading(false);if(failures.length)setError(failures.join('\n'));else setNotice('Contracts saved. Open each one to check its rates.');await refresh();setMode('contracts');if(file.current)file.current.value='';}
 function search(){setError('');try{nights(from,to);if(!validDate(bookingDate))throw Error('Choose a valid booking date.');if(rooms.some(r=>r.ages.some(a=>a===null)))throw Error('Choose each child’s age at travel.');setCriteria({from,to,bookingDate,plan:plan as StaySearch['plan'],rooms:rooms as StaySearch['rooms']});setCalendar(false);setGuests(false);}catch(e){setError((e as Error).message);}}
 function quoteFor(h:Hotel,roomType?:string){roomType=roomType||roomFilter||undefined;const q=criteria;if(!q)return {complete:false,total:null,currency:'',lines:[],issues:['Select dates and search.'],roomType:''} as HotelQuote;const cs=data.contracts.filter(c=>c.hotelId===h.id);const types=roomType?[roomType]:[...new Set(cs.flatMap(c=>[...c.rates.map(r=>r.room),...(c.upgrades||[]).map(u=>u.room)]))];const all=types.map(type=>quoteStay(cs,{...q,roomType:type}));return all.filter(q=>q.complete).sort((a,b)=>(a.total||0)-(b.total||0))[0]||all[0]||quoteStay(cs,q);}
 function sourceRates(h:Hotel,roomType?:string){return listedRates(data.contracts.filter(c=>c.hotelId===h.id),criteria?{...criteria,roomType:roomType||roomFilter||undefined}:null);}
 function sourcePrice(h:Hotel,roomType?:string){if(criteria){const stay=listedStay(data.contracts.filter(c=>c.hotelId===h.id),{...criteria,roomType:roomType||undefined});if(stay)return currency(stay.total,stay.currency);}const rates=sourceRates(h,roomType);const currencies=new Set(rates.map(r=>r.currency));if(!rates.length)return '0';if(currencies.size!==1)return 'View listed rates';return currency(Math.min(...rates.map(r=>r.amount!)),rates[0].currency);}
 const cards=useMemo(()=>data.hotels.filter(h=>data.contracts.some(c=>c.hotelId===h.id)&&(!place||[h.place,h.name].some(s=>s.toLowerCase().includes(place.toLowerCase())))&&h.name.toLowerCase().includes(hotelText.toLowerCase())&&(!stars.length||stars.includes(h.stars||0))&&(!roomFilter||data.contracts.filter(c=>c.hotelId===h.id).some(c=>c.rates.some(r=>r.room===roomFilter)||(c.upgrades||[]).some(u=>u.room===roomFilter)))).map(h=>({hotel:h,quote:quoteFor(h)})).filter(x=>(missing||x.quote.complete)&&(!budget||x.quote.complete&&x.quote.currency==='USD'&&x.quote.total!<=Number(budget))).sort((a,b)=>sort==='price'?(a.quote.complete?0:1)-(b.quote.complete?0:1)||(a.quote.currency===b.quote.currency?(a.quote.total||0)-(b.quote.total||0):a.quote.currency.localeCompare(b.quote.currency)):a.hotel.name.localeCompare(b.hotel.name)),[data,criteria,place,hotelText,stars,missing,budget,sort,roomFilter]);
 async function showDetail(h:Hotel){setDetail({hotel:h,quote:quoteFor(h),roomType:quoteFor(h).roomType});setSelectedRoom(quoteFor(h).roomType);setDetailTab('Rooms');setProposalId('');try{const r=await fetch('/api/proposals');if(r.ok)setProposals(await r.json());}catch{setProposals([]);}}
 async function addStay(withoutPrice:boolean){if(!detail||!criteria)return;setAdding(true);setError('');try{const p=proposals.find(p=>p.id===proposalId);const saved=await request('add-to-proposal',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({hotelId:detail.hotel.id,search:{...criteria,roomType:selectedRoom||undefined},proposalId,proposalVersion:p?.version,withoutPrice})});setDetail(null);setNotice('Hotel added to proposal.');onProposal(saved);}catch(e){setError((e as Error).message);}finally{setAdding(false);}}
 const filterPanel=(scope:string)=><>{scope==='desktop'&&<h3>Filter by</h3>}<label>Hotel name<input value={hotelText} onChange={e=>setHotelText(e.target.value)} placeholder="Search hotel name"/></label><fieldset><legend><Star size={16}/>Star category</legend>{[3,4,5,0].map(n=><label className="ht-check" key={n}><input type="checkbox" checked={stars.includes(n)} onChange={e=>setStars(old=>e.target.checked?[...old,n]:old.filter(x=>x!==n))}/>{n?n+' stars':'Not confirmed'}</label>)}</fieldset><fieldset><legend><Utensils size={16}/>Meal plan</legend>{[['BB','Breakfast'],['HB','Half board'],['FB','Full board'],['AI','All inclusive'],['RO','Room only']].map(([v,l])=><label className="ht-check" key={v}><input type="radio" name={'ht-plan-'+scope} checked={plan===v} onChange={()=>{setPlan(v);if(criteria)setCriteria({...criteria,plan:v as any})}}/>{v} · {l}</label>)}</fieldset><label>Room type<select value={roomFilter} onChange={e=>setRoomFilter(e.target.value)}><option value="">Any room</option>{[...new Set(data.contracts.flatMap(c=>[...c.rates.map(r=>r.room),...(c.upgrades||[]).map(u=>u.room)]))].sort().map(r=><option key={r}>{r}</option>)}</select></label><label>Booking date<input type="date" value={bookingDate} onChange={e=>{setBookingDate(e.target.value)}}/></label><label>Maximum stay total (USD)<input type="number" min="0" step="1" value={budget} onChange={e=>setBudget(e.target.value)} placeholder="No limit"/></label><label className="ht-check"><input type="checkbox" checked={missing} onChange={e=>setMissing(e.target.checked)}/>Include rates needing checks</label><button className="ht-text" onClick={()=>{setStars([]);setPlan('HB');setHotelText('');setRoomFilter('');setBudget('');setMissing(true);if(criteria)setCriteria({...criteria,plan:'HB'})}}>Clear filters</button></>;
 return <div className="ht-app">
 <header className="ht-hero"><div className="ht-wrap"><div className="ht-heading"><div><p className="ht-kicker">BBEAR TRAVELS</p><h1>Hotels</h1></div><button className="ht-white" onClick={()=>{setUploadOpen(true);setProgress('')}}><Upload size={18}/>Upload contracts</button></div><nav className="ht-tabs"><button className={mode==='hotels'?'selected':''} onClick={()=>setMode('hotels')}><BedDouble size={18}/>Find a hotel</button><button className={mode==='contracts'?'selected':''} onClick={()=>setMode('contracts')}><FileText size={18}/>Contracts <small>{data.contracts.length}</small></button></nav>
 {mode==='hotels'&&<div className="ht-search"><label className="ht-destination"><BedDouble size={22}/><span><small>Destination or hotel</small><input list="ht-places" placeholder="Where are they staying?" value={place} onChange={e=>setPlace(e.target.value)}/><datalist id="ht-places">{[...new Set(data.hotels.map(h=>h.place).filter(Boolean))].map(p=><option key={p}>{p}</option>)}</datalist></span>{place&&<button aria-label="Clear destination" onClick={()=>setPlace('')}><X size={16}/></button>}</label><button className="ht-search-part" onClick={()=>{setCalendar(true);setDateStep('from');setMonth((validDate(from)?new Date(from+'T12:00:00'):new Date()).getMonth());setYear((validDate(from)?new Date(from+'T12:00:00'):new Date()).getFullYear())}}><CalendarDays size={22}/><span><small>Select dates</small>{display(from)} — {display(to)}</span></button><button className="ht-search-part" onClick={()=>setGuests(true)}><UsersRound size={23}/><span><small>Rooms and guests</small>{rooms.reduce((n,r)=>n+r.adults,0)} {rooms.reduce((n,r)=>n+r.adults,0)===1?'adult':'adults'} · {rooms.reduce((n,r)=>n+r.ages.length,0)} {rooms.reduce((n,r)=>n+r.ages.length,0)===1?'child':'children'} · {rooms.length} {rooms.length===1?'room':'rooms'}</span><ChevronDown size={16}/></button><button className="ht-search-button" onClick={search}><Search size={18}/>Search</button></div>}
 </div></header>
 <div className="ht-wrap ht-body">{error&&<div className="ht-alert" role="alert"><AlertCircle size={18}/><span>{error}</span><button aria-label="Dismiss error" onClick={()=>setError('')}><X size={18}/></button></div>}{notice&&<div className="ht-success" role="status"><Check size={18}/>{notice}<button aria-label="Dismiss message" onClick={()=>setNotice('')}><X size={18}/></button></div>}{setup&&<div className="ht-setup"><ShieldCheck size={25}/><div><h3>Connect hotel storage</h3><p>Run the hotel setup SQL in Supabase, then refresh. Existing proposals are kept.</p></div><button onClick={()=>void refresh()}>Refresh</button></div>}
 {mode==='hotels'?<div className="ht-layout"><aside className="ht-filter">{filterPanel('desktop')}</aside><section><div className="ht-result-head"><div><h2>{place||'Your hotels'} {!loading&&<span>· {cards.length} {cards.length===1?'hotel':'hotels'}</span>}</h2><p>{criteria?`${nights(criteria.from,criteria.to).length} nights · ${criteria.plan}`:'Choose dates and guests to check rates.'}</p></div><div className="ht-view"><button className={!grid?'active':''} aria-label="List view" onClick={()=>setGrid(false)}><List size={18}/></button><button className={grid?'active':''} aria-label="Grid view" onClick={()=>setGrid(true)}><LayoutGrid size={18}/></button></div></div><div className="ht-sort"><button className="ht-filter-mobile" onClick={()=>setFilters(true)}><SlidersHorizontal size={17}/>Filters</button><label>Sort by<select value={sort} onChange={e=>setSort(e.target.value)}><option value="name">Hotel name</option><option value="price">Known price, lowest first</option></select></label></div>
 {loading?<div className="ht-empty"><LoaderCircle className="spin"/>Loading hotels…</div>:!cards.length?<div className="ht-empty"><Building2 size={40}/><h3>{data.hotels.length?'No matching hotels':'Add your hotel contracts'}</h3><p>{data.hotels.length?'Try another destination or clear the filters.':'Upload PDF or Word contracts to begin.'}</p>{data.hotels.length?<button className="ht-primary" onClick={()=>{setPlace('');setStars([]);setHotelText('');setRoomFilter('');setBudget('');setMissing(true)}}><SlidersHorizontal size={17}/>Clear filters</button>:<button className="ht-primary" onClick={()=>setUploadOpen(true)}><Upload size={17}/>Upload contracts</button>}</div>:<div className={grid?'ht-results ht-grid':'ht-results'}>{cards.map(({hotel:h,quote:q})=><article className="ht-card" key={h.id}><div className="ht-card-photo">{hotelPhoto(h)?(officialHotelPhoto(h)?<Image src={officialHotelPhoto(h)!.image} alt={h.name} fill sizes="(max-width: 760px) 40vw, (max-width: 1100px) 180px, 220px" quality={68} loading="lazy" placeholder="empty"/>:<img referrerPolicy="no-referrer" src={hotelPhoto(h)} alt={h.name} loading="lazy"/>):<div><Building2 size={46}/><span>Hotel photo not added</span></div>}</div><div className="ht-card-info"><h3><button onClick={()=>void showDetail(h)}>{h.name}</button>{h.stars&&<span className="ht-stars" aria-label={h.stars+' stars'}>{Array.from({length:h.stars},(_,i)=><Star key={i} size={14} fill="currentColor"/>)}</span>}</h3><p className="ht-place"><MapPin size={14}/>{h.place||'Location not confirmed'}</p>{!h.stars&&<span className="ht-category">Category not confirmed</span>}<div className="ht-room-info"><b>{q.roomType||'View contracted rooms'}</b><span>{criteria?.plan||'All listed plans'} · {data.contracts.filter(c=>c.hotelId===h.id&&c.status!=='Archived').length} contracts</span><span className={q.complete?'ht-good':'ht-pending'}>{q.complete?<Check size={15}/>:<AlertCircle size={15}/>} {q.complete?'Contract rate found':'Rate needs checking'}</span></div></div><div className="ht-card-price"><small>{q.complete?'Stay total':'Contract-listed amount'}</small><strong>{q.complete?currency(q.total,q.currency):sourcePrice(h,q.roomType)}</strong><span>{q.complete?'Room confirmation needed':sourceRates(h,q.roomType).length?'From · listed base rate':'Rate not provided'}</span>{!q.complete&&sourceRates(h,q.roomType).length>0&&<small>{criteria?'Listed room total · '+nights(criteria.from,criteria.to).length+' nights':'All contract dates · search for your stay'}</small>}<button className="ht-primary" onClick={()=>void showDetail(h)}>View rooms<ChevronRight size={16}/></button></div></article>)}</div>}</section></div>:<section className="ht-contracts"><div className="ht-result-head"><div><h2>Hotel contracts</h2><p>Keep seasonal rates and updates together under each hotel.</p></div><div className="ht-row"><button className="ht-outline" onClick={async()=>{try{const records=await request('backup');const url=URL.createObjectURL(new Blob([JSON.stringify(records,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bbear-hotel-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){setError((e as Error).message)}}}>Download records</button><button className="ht-outline" onClick={()=>void refresh()}><RefreshCw size={17}/>Refresh</button></div></div><div className="ht-contract-table"><table><thead><tr><th>Hotel / document</th><th>Rates</th><th>Status</th><th/></tr></thead><tbody>{data.contracts.map(c=><tr key={c.id}><td><b>{data.hotels.find(h=>h.id===c.hotelId)?.name}</b><small>{c.name}</small><small>{c.rates.length?'Latest listed night: '+display(c.rates.map(r=>r.to).sort().at(-1)!):'Rate dates not confirmed'}</small></td><td>{c.rates.length}</td><td><span className={c.status==='Reviewed'?'ht-good':'ht-pending'}>{c.status==='Draft'?'Needs checking':c.status}</span></td><td><button className="ht-outline" onClick={()=>void openReview(c.id)}>Review<ArrowUpRight size={15}/></button></td></tr>)}</tbody></table>{!data.contracts.length&&<div className="ht-empty">No contracts yet.</div>}</div></section>}
 </div>
 {calendar&&<div className="ht-overlay"><div className="ht-dialog ht-date-dialog" role="dialog" aria-modal="true" aria-label="Select dates"><div className="ht-dialog-head"><div><h2>Select dates</h2><p>{dateStep==='from'?'Choose check-in':'Choose check-out'}</p></div><button className="ht-icon" aria-label="Close dates" onClick={()=>setCalendar(false)}><X/></button></div><div className="ht-date-inputs"><label>Check-in<input type="date" value={from} onChange={e=>{setFrom(e.target.value);setDateStep('to')}}/></label><label>Check-out<input type="date" value={to} min={from} onChange={e=>setTo(e.target.value)}/></label></div><div className="ht-month-nav"><button className="ht-icon" aria-label="Previous month" onClick={()=>{const d=new Date(year,month-1);setYear(d.getFullYear());setMonth(d.getMonth())}}><ChevronLeft/></button><span>{display(from)} — {display(to)}</span><button className="ht-icon" aria-label="Next month" onClick={()=>{const d=new Date(year,month+1);setYear(d.getFullYear());setMonth(d.getMonth())}}><ChevronRight/></button></div><div className="ht-calendars">{[0,1].map(offset=>{const d=new Date(year,month+offset,1);return <Calendar key={offset} year={d.getFullYear()} month={d.getMonth()} from={from} to={to} onSelect={s=>{if(dateStep==='from'){setFrom(s);if(s>=to)setTo(iso(new Date(Date.parse(s)+86400000)));setDateStep('to')}else if(s<=from){setFrom(s);setDateStep('to')}else{setTo(s);setDateStep('from')}}}/>})}</div><div className="ht-dialog-foot"><span>{from<to?Math.round((Date.parse(to)-Date.parse(from))/86400000)+' nights':'Choose a departure after arrival'}</span><button className="ht-primary" disabled={!from||!to||from>=to} onClick={()=>setCalendar(false)}>Done</button></div></div></div>}
 {guests&&<div className="ht-overlay"><div className="ht-dialog ht-guest-dialog" role="dialog" aria-modal="true" aria-label="Rooms and guests"><div className="ht-dialog-head"><h2>Rooms and guests</h2><button className="ht-icon" aria-label="Close guests" onClick={()=>setGuests(false)}><X/></button></div><div className="ht-dialog-scroll">{rooms.map((r,i)=><div className="ht-guest-room" key={i}><div className="ht-row"><h3>Room {i+1}</h3>{rooms.length>1&&<button className="ht-text" onClick={()=>setRooms(rooms.filter((_,j)=>i!==j))}>Remove</button>}</div><Counter label="Adults" value={r.adults} min={1} max={8} change={n=>setRooms(rooms.map((x,j)=>i===j?{...x,adults:n}:x))}/><Counter label="Children" value={r.ages.length} min={0} max={6} change={n=>setRooms(rooms.map((x,j)=>i===j?{...x,ages:n<x.ages.length?x.ages.slice(0,n):[...x.ages,null]}:x))}/>{r.ages.map((a,j)=><label className="ht-age" key={j}>Child {j+1} · age at travel<select value={a===null?'':a} onChange={e=>setRooms(rooms.map((x,k)=>k===i?{...x,ages:x.ages.map((v,l)=>l===j?Number(e.target.value):v)}:x))}><option value="" disabled>Select age</option>{Array.from({length:18},(_,n)=><option value={n} key={n}>{n===0?'Under 1':n===1?'1 year':n+' years'}</option>)}</select></label>)}</div>)}<button className="ht-outline" disabled={rooms.length>=20} onClick={()=>setRooms([...rooms,{adults:2,ages:[]}])}><Plus size={17}/>Add room</button></div><div className="ht-dialog-foot"><p>Use ages at the time of travel.</p><button className="ht-primary" onClick={()=>setGuests(false)}>Done</button></div></div></div>}
 {filters&&<div className="ht-overlay"><div className="ht-dialog ht-filter-sheet" role="dialog" aria-modal="true" aria-label="Hotel filters"><div className="ht-dialog-head"><h2>Filters</h2><button className="ht-icon" aria-label="Close filters" onClick={()=>setFilters(false)}><X/></button></div><div className="ht-dialog-scroll">{filterPanel('mobile')}</div><div className="ht-dialog-foot"><button className="ht-primary" onClick={()=>setFilters(false)}>Show hotels</button></div></div></div>}
 {uploadOpen&&<div className="ht-overlay"><div className="ht-dialog ht-upload-dialog" role="dialog" aria-modal="true" aria-label="Upload hotel contracts"><div className="ht-dialog-head"><h2>Upload contracts</h2><button className="ht-icon" disabled={uploading} aria-label="Close upload" onClick={()=>setUploadOpen(false)}><X/></button></div><div className="ht-dialog-scroll"><label>Add to hotel<select value={uploadHotel} disabled={uploading} onChange={e=>setUploadHotel(e.target.value)}><option value="">{data.aiReady?'Identify from document':'New hotel · review after upload'}</option>{data.hotels.map(h=><option key={h.id} value={h.id}>{h.name}</option>)}</select></label><p className="ht-hint">Choose an existing hotel for another season or update. Documents stay separate.</p><div className="ht-drop"><FileText size={40}/><h3>PDF or Word contracts</h3><p>Select several files · up to 4 MB each</p><button className="ht-primary" disabled={uploading||setup} onClick={()=>file.current?.click()}>{uploading?<LoaderCircle className="spin" size={17}/>:<Upload size={17}/>}Choose files</button><input hidden ref={file} multiple type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={e=>{const f=Array.from(e.target.files||[]);if(f.length)void upload(f)}}/></div><p className="ht-hint">{data.aiReady?'Automatic reading is connected. Extracted rates still need review.':'Automatic reading is not connected. Source files and prepared drafts can still be reviewed.'}</p>{progress&&<p role="status" className="ht-progress">{progress}</p>}{error&&<p className="ht-inline-error" role="alert">{error}</p>}</div><div className="ht-dialog-foot"><span>{uploading?'Keep this screen open until the files finish.':'Duplicate files are skipped.'}</span><button className="ht-outline" disabled={uploading} onClick={()=>{setUploadOpen(false);setMode('contracts')}}>View contracts</button></div></div></div>}
 {draft&&hotel&&<div className="ht-overlay"><div className="ht-dialog ht-review" role="dialog" aria-modal="true" aria-label="Review hotel contract"><div className="ht-dialog-head"><div><h2>{hotel.name}</h2><p>{draft.name}</p></div><div className="ht-row"><button className="ht-outline" disabled={saving} onClick={()=>void saveReview()}>{saving?<LoaderCircle size={16} className="spin"/>:<Check size={16}/>}Save changes</button><button className="ht-icon" disabled={saving} aria-label="Close contract review" onClick={closeReview}><X/></button></div></div>{error&&<p className="ht-inline-error" role="alert">{error}</p>}<div className="ht-review-layout"><aside className="ht-source"><div className="ht-row"><b>Original contract</b><a href={'/api/hotels/contract/'+draft.id+'/file'} target="_blank" rel="noreferrer">Open original<ArrowUpRight size={14}/></a></div>{draft.mime==='application/pdf'?<ContractViewer url={'/api/hotels/contract/'+draft.id+'/file'} pages={draft.pages}/>:<div className="ht-source-text">{draft.pages.map(p=><section key={p.number}><b>Document text · {p.number}</b><pre>{p.text}</pre></section>)}</div>}</aside><form ref={reviewForm} className="ht-review-editor" onSubmit={e=>{e.preventDefault();void saveReview()}}><div className="ht-inner-tabs">{['Rates','Meals','Rules','Hotel','History'].map(t=><button type="button" key={t} className={reviewTab===t?'active':''} onClick={()=>setReviewTab(t)}>{t}</button>)}</div>
 {reviewTab==='Rates'&&<><div className="ht-row"><h3>Contract rates</h3><button type="button" className="ht-outline" onClick={()=>patch('rates',[...draft.rates,{id:uid(),room:'Standard',plan:'BB',occupancy:2,from,to,amount:null,page:1,source:'',checked:false}])}><Plus size={16}/>Add rate</button></div><p className="ht-hint">{draft.readStatus}. Check each value against the original.</p><label>Hotel<select value={draft.hotelId} onChange={e=>{const h=data.hotels.find(h=>h.id===e.target.value);patch('hotelId',e.target.value);if(h)setHotel(h)}}>{data.hotels.map(h=><option key={h.id} value={h.id}>{h.name}</option>)}</select></label><div className="ht-two"><label>Currency<select value={draft.currency} onChange={e=>patch('currency',e.target.value as any)}><option value="">Not confirmed</option><option>USD</option><option>LKR</option><option>INR</option></select></label><label>Status<select value={draft.status} onChange={e=>{setDraft({...draft,status:e.target.value as any});setDirty(true)}}><option value="Draft">Needs checking</option><option value="Reviewed">Reviewed</option><option value="Archived">Archived</option></select></label></div><label className="ht-check"><input type="checkbox" checked={draft.unitConfirmed} onChange={e=>patch('unitConfirmed',e.target.checked)}/>Base rates confirmed per room per night</label><label className="ht-check"><input type="checkbox" checked={draft.nightlyConfirmed} onChange={e=>patch('nightlyConfirmed',e.target.checked)}/>Each occupied night uses its own date band</label>
 {draft.notes.split('UNRESOLVED SUITE VALUES')[1]?.trim()&&<details className="ht-question"><summary>Suite prices needing a meal plan</summary><pre className="ht-policy-text">{draft.notes.split('UNRESOLVED SUITE VALUES')[1].trim()}</pre><p>Keep these unpriced until the meal plan and charging basis are confirmed.</p></details>}<div className="ht-rate-pagination"><span>{draft.rates.filter(r=>r.checked).length} of {draft.rates.length} checked</span><button type="button" className="ht-outline" disabled={ratePage===0} onClick={()=>setRatePage(n=>n-1)}>Previous</button><span>{ratePage+1} / {Math.max(1,Math.ceil(draft.rates.length/15))}</span><button type="button" className="ht-outline" disabled={(ratePage+1)*15>=draft.rates.length} onClick={()=>setRatePage(n=>n+1)}>Next</button></div><div className="ht-rate-list">{draft.rates.slice(ratePage*15,(ratePage+1)*15).map((r,i)=><div className="ht-rate" key={r.id}><div className="ht-row"><b>Rate {ratePage*15+i+1}</b><button type="button" className="ht-text" onClick={()=>{setConfirmAction(r.id)}}>Remove</button></div><div className="ht-two"><label>Room<input required value={r.room} onChange={e=>patchRate(r.id,'room',e.target.value)}/></label><label>Adults<input required type="number" min="1" max="8" value={r.occupancy} onChange={e=>patchRate(r.id,'occupancy',Number(e.target.value))}/></label></div><div className="ht-three"><label>Plan<select value={r.plan} onChange={e=>patchRate(r.id,'plan',e.target.value)}>{['BB','HB','FB','AI','RO'].map(p=><option key={p}>{p}</option>)}</select></label><label>Amount<Amount key={r.id+'amount'} value={r.amount} change={n=>patchRate(r.id,'amount',n)}/></label><label>Source page<input type="number" min="1" max={draft.pages.length||1} value={r.page} onChange={e=>patchRate(r.id,'page',Number(e.target.value))}/></label></div><div className="ht-two"><label>From<input required type="date" value={r.from} onChange={e=>patchRate(r.id,'from',e.target.value)}/></label><label>Through<input required type="date" min={r.from} value={r.to} onChange={e=>patchRate(r.id,'to',e.target.value)}/></label></div><label>Source / clarification<textarea rows={2} value={r.source} onChange={e=>patchRate(r.id,'source',e.target.value)}/></label><label className="ht-check"><input type="checkbox" checked={r.checked} onChange={e=>patchRate(r.id,'checked',e.target.checked)}/>Checked against source</label></div>)}</div>{!draft.rates.length&&<p className="ht-pending">No rates extracted. Add the source values or connect automatic reading.</p>}<button type="button" className="ht-outline" disabled={saving||dirty} onClick={async()=>{setSaving(true);try{const c=await request('contract/'+draft.id+'/extract',{method:'POST'});setDraft(c);const info=await request();setData(info);setHotel(info.hotels.find((h:Hotel)=>h.id===c.hotelId)||null)}catch(e){setError((e as Error).message)}finally{setSaving(false)}}}><RefreshCw size={16}/>Read document again</button></>}
 {reviewTab==='Meals'&&<><div className="ht-row"><h3>Separate meal prices</h3><button type="button" className="ht-outline" onClick={()=>patch('meals',[...draft.meals,{id:uid(),label:'Lunch',adult:null,child:null,unit:'',note:'',page:1}])}><Plus size={16}/>Add meal</button></div><p className="ht-hint">These do not automatically change BB, HB or FB room prices.</p>{draft.meals.map(m=><div className="ht-rate" key={m.id}><label>Meal<input value={m.label} onChange={e=>patch('meals',draft.meals.map(x=>x.id===m.id?{...x,label:e.target.value}:x))}/></label><div className="ht-two"><label>Adult<Amount value={m.adult} change={n=>patch('meals',draft.meals.map(x=>x.id===m.id?{...x,adult:n}:x))}/></label><label>Child<Amount value={m.child} change={n=>patch('meals',draft.meals.map(x=>x.id===m.id?{...x,child:n}:x))}/></label></div><label>Charging unit<input value={m.unit} onChange={e=>patch('meals',draft.meals.map(x=>x.id===m.id?{...x,unit:e.target.value}:x))} placeholder="Only as specified in the contract"/></label><label>Conditions<textarea value={m.note} onChange={e=>patch('meals',draft.meals.map(x=>x.id===m.id?{...x,note:e.target.value}:x))}/></label><button type="button" className="ht-text" onClick={()=>patch('meals',draft.meals.filter(x=>x.id!==m.id))}>Remove meal</button></div>)}</>}
 {reviewTab==='Rules'&&<><h3>Questions to check</h3><p className="ht-hint">Record the supplier’s clarification. Unanswered questions keep pricing incomplete.</p>{draft.issues.map(i=><label className="ht-question" key={i.id}><span><AlertCircle size={16}/>{i.text}</span><textarea rows={3} value={i.resolution} placeholder="Supplier clarification and source" onChange={e=>patch('issues',draft.issues.map(x=>x.id===i.id?{...x,resolution:e.target.value}:x))}/></label>)}<button type="button" className="ht-outline" onClick={()=>patch('issues',[...draft.issues,{id:uid(),text:'Additional supplier condition',resolution:''}])}><Plus size={16}/>Add question</button><h3>Meal-plan adjustments</h3>{draft.boards.map((b,i)=><div className="ht-rate" key={b.id}><div className="ht-row"><b>{b.from} → {b.to}</b><button type="button" className="ht-text" onClick={()=>patch('boards',draft.boards.filter(x=>x.id!==b.id))}>Remove</button></div><div className="ht-three"><label>From<select value={b.from} onChange={e=>patch('boards',draft.boards.map(x=>x.id===b.id?{...x,from:e.target.value as any,checked:false}:x))}>{['BB','HB','FB','AI','RO'].map(p=><option key={p}>{p}</option>)}</select></label><label>To<select value={b.to} onChange={e=>patch('boards',draft.boards.map(x=>x.id===b.id?{...x,to:e.target.value as any,checked:false}:x))}>{['BB','HB','FB','AI','RO'].map(p=><option key={p}>{p}</option>)}</select></label><label>Adult/person/night<Amount signed value={b.adult} change={n=>patch('boards',draft.boards.map(x=>x.id===b.id?{...x,adult:n??0,checked:false}:x))}/></label></div><label>Child/person/night<Amount signed value={b.child} change={n=>patch('boards',draft.boards.map(x=>x.id===b.id?{...x,child:n,checked:false}:x))}/></label><label>Source<textarea value={b.source} onChange={e=>patch('boards',draft.boards.map(x=>x.id===b.id?{...x,source:e.target.value,checked:false}:x))}/></label><label className="ht-check"><input type="checkbox" checked={b.checked} onChange={e=>patch('boards',draft.boards.map(x=>x.id===b.id?{...x,checked:e.target.checked}:x))}/>Adjustment verified</label></div>)}<button type="button" className="ht-outline" onClick={()=>patch('boards',[...draft.boards,{id:uid(),from:'HB',to:'FB',adult:0,child:null,source:'',checked:false}])}><Plus size={16}/>Add explicit adjustment</button><h3>Children</h3>{draft.children.map(b=><div className="ht-rate" key={b.id}><div className="ht-three"><label>Age from<input type="number" min="0" max="17" value={b.min} onChange={e=>patch('children',draft.children.map(x=>x.id===b.id?{...x,min:Number(e.target.value),checked:false}:x))}/></label><label>Under age<input type="number" min="1" max="18" value={b.max} onChange={e=>patch('children',draft.children.map(x=>x.id===b.id?{...x,max:Number(e.target.value),checked:false}:x))}/></label><label>Maximum children/room<input type="number" min="0" max="6" value={b.maxPerRoom} onChange={e=>patch('children',draft.children.map(x=>x.id===b.id?{...x,maxPerRoom:Number(e.target.value),checked:false}:x))}/></label></div><div className="ht-two"><label>Plan<select value={b.plan} onChange={e=>patch('children',draft.children.map(x=>x.id===b.id?{...x,plan:e.target.value as any,checked:false}:x))}>{['BB','HB','FB','AI','RO'].map(p=><option key={p}>{p}</option>)}</select></label><label>Child/person/night<Amount value={b.amount} change={n=>patch('children',draft.children.map(x=>x.id===b.id?{...x,amount:n,checked:false}:x))}/></label></div><label>Room sharing and source<textarea value={b.source} onChange={e=>patch('children',draft.children.map(x=>x.id===b.id?{...x,source:e.target.value,checked:false}:x))}/></label><label className="ht-check"><input type="checkbox" checked={b.checked} onChange={e=>patch('children',draft.children.map(x=>x.id===b.id?{...x,checked:e.target.checked}:x))}/>Child rate and room sharing verified</label><button type="button" className="ht-text" onClick={()=>patch('children',draft.children.filter(x=>x.id!==b.id))}>Remove</button></div>)}<button type="button" className="ht-outline" onClick={()=>patch('children',[...draft.children,{id:uid(),min:0,max:6,maxPerRoom:0,plan:'HB',amount:null,source:'',checked:false}])}><Plus size={16}/>Add child rule</button><h3>Compulsory date charges</h3>{draft.events.map(ev=><div className="ht-rate" key={ev.id}><label>Night<input type="date" value={ev.date} onChange={e=>patch('events',draft.events.map(x=>x.id===ev.id?{...x,date:e.target.value,checked:false}:x))}/></label><div className="ht-two"><label>Adult/person<Amount value={ev.adult} change={n=>patch('events',draft.events.map(x=>x.id===ev.id?{...x,adult:n,checked:false}:x))}/></label><label>Child/person<Amount value={ev.child} change={n=>patch('events',draft.events.map(x=>x.id===ev.id?{...x,child:n,checked:false}:x))}/></label></div><fieldset><legend>Plans</legend><div className="ht-inline-options">{['BB','HB','FB','AI','RO'].map(p=><label className="ht-check" key={p}><input type="checkbox" checked={ev.plans.includes(p as any)} onChange={e=>patch('events',draft.events.map(x=>x.id===ev.id?{...x,plans:e.target.checked?[...x.plans,p as any]:x.plans.filter(v=>v!==p),checked:false}:x))}/>{p}</label>)}</div></fieldset><div className="ht-two"><label>Child charge from age<Amount value={ev.childMin??null} change={n=>patch('events',draft.events.map(x=>x.id===ev.id?{...x,childMin:n,checked:false}:x))}/></label><label>Child charge under age<Amount value={ev.childMax??null} change={n=>patch('events',draft.events.map(x=>x.id===ev.id?{...x,childMax:n,checked:false}:x))}/></label></div><label>Source and age rules<textarea value={ev.source} onChange={e=>patch('events',draft.events.map(x=>x.id===ev.id?{...x,source:e.target.value,checked:false}:x))}/></label><label className="ht-check"><input type="checkbox" checked={ev.checked} onChange={e=>patch('events',draft.events.map(x=>x.id===ev.id?{...x,checked:e.target.checked}:x))}/>Charge verified</label><button type="button" className="ht-text" onClick={()=>patch('events',draft.events.filter(x=>x.id!==ev.id))}>Remove</button></div>)}<button type="button" className="ht-outline" onClick={()=>patch('events',[...draft.events,{id:uid(),date:from,plans:['HB'],adult:null,child:null,childMin:null,childMax:null,source:'',checked:false}])}><Plus size={16}/>Add date charge</button><h3>Room upgrades</h3>{(draft.upgrades||[]).map(u=><div className="ht-rate" key={u.id}><div className="ht-two"><label>Upgraded room<input value={u.room} onChange={e=>patch('upgrades',(draft.upgrades||[]).map(x=>x.id===u.id?{...x,room:e.target.value,checked:false}:x))}/></label><label>Base room<input value={u.baseRoom} onChange={e=>patch('upgrades',(draft.upgrades||[]).map(x=>x.id===u.id?{...x,baseRoom:e.target.value,checked:false}:x))}/></label></div><label>Per room per night<Amount value={u.amount} change={n=>patch('upgrades',(draft.upgrades||[]).map(x=>x.id===u.id?{...x,amount:n,checked:false}:x))}/></label><label>Source<textarea value={u.source} onChange={e=>patch('upgrades',(draft.upgrades||[]).map(x=>x.id===u.id?{...x,source:e.target.value,checked:false}:x))}/></label><label className="ht-check"><input type="checkbox" checked={u.checked} onChange={e=>patch('upgrades',(draft.upgrades||[]).map(x=>x.id===u.id?{...x,checked:e.target.checked}:x))}/>Upgrade and room eligibility verified</label><button type="button" className="ht-text" onClick={()=>patch('upgrades',(draft.upgrades||[]).filter(x=>x.id!==u.id))}>Remove</button></div>)}<button type="button" className="ht-outline" onClick={()=>patch('upgrades',[...(draft.upgrades||[]),{id:uid(),room:'',baseRoom:'',amount:null,page:1,source:'',checked:false}])}><Plus size={16}/>Add room upgrade</button><h3>Early-booking offers</h3><p className="ht-hint">Applies only when the whole stay fits the travel window. Offers are not combined.</p><label className="ht-check"><input type="checkbox" checked={draft.offerPolicyConfirmed||false} onChange={e=>patch('offerPolicyConfirmed',e.target.checked)}/>Hotel confirms the best single eligible offer applies without stacking</label>{(draft.offers||[]).map(o=><div className="ht-rate" key={o.id}><div className="ht-two"><label>Travel from<input type="date" value={o.from} onChange={e=>patch('offers',(draft.offers||[]).map(x=>x.id===o.id?{...x,from:e.target.value,checked:false}:x))}/></label><label>Travel through<input type="date" value={o.to} onChange={e=>patch('offers',(draft.offers||[]).map(x=>x.id===o.id?{...x,to:e.target.value,checked:false}:x))}/></label></div><div className="ht-three"><label>Book days ahead<input type="number" min="0" max="1000" value={o.leadDays} onChange={e=>patch('offers',(draft.offers||[]).map(x=>x.id===o.id?{...x,leadDays:Number(e.target.value),checked:false}:x))}/></label><label>Minimum nights<input type="number" min="1" max="60" value={o.minNights} onChange={e=>patch('offers',(draft.offers||[]).map(x=>x.id===o.id?{...x,minNights:Number(e.target.value),checked:false}:x))}/></label><label>Discount (%)<Amount value={o.percent} change={n=>patch('offers',(draft.offers||[]).map(x=>x.id===o.id?{...x,percent:n??0,checked:false}:x))}/></label></div><fieldset><legend>Discount applies to</legend><div className="ht-inline-options">{[['base','Base room'],['board','Meal change'],['child','Children'],['event','Date charge'],['upgrade','Room upgrade']].map(([v,l])=><label className="ht-check" key={v}><input type="checkbox" checked={o.components.includes(v as any)} onChange={e=>patch('offers',(draft.offers||[]).map(x=>x.id===o.id?{...x,components:e.target.checked?[...x.components,v as any]:x.components.filter(k=>k!==v),checked:false}:x))}/>{l}</label>)}</div></fieldset><label>Source and eligibility<textarea value={o.source} onChange={e=>patch('offers',(draft.offers||[]).map(x=>x.id===o.id?{...x,source:e.target.value,checked:false}:x))}/></label><label className="ht-check"><input type="checkbox" checked={o.checked} onChange={e=>patch('offers',(draft.offers||[]).map(x=>x.id===o.id?{...x,checked:e.target.checked}:x))}/>Offer scope and eligibility verified</label><button type="button" className="ht-text" onClick={()=>patch('offers',(draft.offers||[]).filter(x=>x.id!==o.id))}>Remove</button></div>)}<button type="button" className="ht-outline" onClick={()=>patch('offers',[...(draft.offers||[]),{id:uid(),from,to,leadDays:90,minNights:1,percent:0,components:['base'],source:'',checked:false}])}><Plus size={16}/>Add offer</button><label>Other conditions<textarea rows={14} value={draft.notes} onChange={e=>patch('notes',e.target.value)}/></label></>}
 {reviewTab==='Hotel'&&<><h3>Hotel details</h3><label>Hotel name<input required value={hotel.name} onChange={e=>{setHotel({...hotel,name:e.target.value});setDirty(true)}}/></label><label>Destination<input value={hotel.place} onChange={e=>{setHotel({...hotel,place:e.target.value});setDirty(true)}}/></label><div className="ht-two"><label>Star category<select value={hotel.stars||''} onChange={e=>{setHotel({...hotel,stars:e.target.value?Number(e.target.value):null});setDirty(true)}}><option value="">Not confirmed</option>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} stars</option>)}</select></label><label>Star category source<input value={hotel.starSource} onChange={e=>{setHotel({...hotel,starSource:e.target.value});setDirty(true)}} placeholder="Verified classification source"/></label></div><div className="ht-hotel-photo">{hotelPhoto(hotel)?<img referrerPolicy="no-referrer" src={hotelPhoto(hotel)} alt={hotel.name}/>:<Building2 size={60}/>}<button type="button" className="ht-outline" onClick={()=>setPhoto(true)}><ImageIcon size={16}/>Choose hotel photo</button></div>{photo&&<div className="ht-photo-select"><div className="ht-row"><b>Choose a verified property photo</b><button type="button" className="ht-icon" aria-label="Close hotel photos" onClick={()=>setPhoto(false)}><X/></button></div><MediaLibrary onChoose={url=>{setHotel({...hotel,photo:url});setDirty(true);setPhoto(false)}}/></div>}</>}
 {reviewTab==='History'&&<><h3>Saved versions</h3><button type="button" className="ht-outline" onClick={async()=>{try{setHistory(await request('contract/'+draft.id+'/history'))}catch(e){setError((e as Error).message)}}}><History size={16}/>Load history</button>{history?.map((v,i)=><div className="ht-rate" key={i}><b>{v.body.status==='Draft'?'Needs checking':v.body.status} · {v.body.rates.length} rates</b><p>{new Date(v.body.updated).toLocaleString()}</p><p>{v.body.name}</p></div>)}</>}
 </form></div><div className="ht-dialog-foot"><span>{dirty?'Unsaved changes':draft.status==='Reviewed'?'Reviewed contract':'Needs checking'} · {draft.rates.length} rates</span><button className="ht-primary" disabled={saving} onClick={()=>void saveReview()}>{saving?'Saving…':'Save changes'}</button></div></div></div>}
 {detail&&<div className="ht-overlay"><div className="ht-dialog ht-detail" role="dialog" aria-modal="true" aria-label="Hotel rooms and rates"><div className="ht-dialog-head"><div><h2>{detail.hotel.name}</h2><p><MapPin size={14}/>{detail.hotel.place||'Location not confirmed'}</p></div><button className="ht-icon" disabled={adding} aria-label="Close hotel details" onClick={()=>setDetail(null)}><X/></button></div><div className="ht-inner-tabs">{['Rooms','Meals','Policies','Contract'].map(t=><button key={t} className={detailTab===t?'active':''} onClick={()=>setDetailTab(t)}>{t}</button>)}</div><div className="ht-dialog-scroll">{error&&<p className="ht-inline-error" role="alert">{error}</p>}{detailTab==='Rooms'&&<><label>Room type<select value={selectedRoom} onChange={e=>{setSelectedRoom(e.target.value);setDetail({...detail,roomType:e.target.value,quote:quoteFor(detail.hotel,e.target.value)})}}>{[...new Set(data.contracts.filter(c=>c.hotelId===detail.hotel.id).flatMap(c=>[...c.rates.map(r=>r.room),...(c.upgrades||[]).map(u=>u.room)]))].map(r=><option key={r}>{r}</option>)}</select></label><div className="ht-stay-total"><span>{criteria?`${display(criteria.from)} — ${display(criteria.to)} · ${nights(criteria.from,criteria.to).length} nights · ${criteria.plan}`:'Search dates and guests first'}</span><strong>{detail.quote.complete?currency(detail.quote.total,detail.quote.currency):(criteria&&listedStay(data.contracts.filter(c=>c.hotelId===detail.hotel.id),{...criteria,roomType:selectedRoom||undefined})?currency(listedStay(data.contracts.filter(c=>c.hotelId===detail.hotel.id),{...criteria,roomType:selectedRoom||undefined})!.total,listedStay(data.contracts.filter(c=>c.hotelId===detail.hotel.id),{...criteria,roomType:selectedRoom||undefined})!.currency):'Rate needs checking')}</strong><span>{detail.quote.complete?'Contract cost · room confirmation needed':'Listed room subtotal · extra charges need checking'}</span></div><section className="ht-listed"><h3>Listed room rates</h3><p className="ht-hint">Amounts from your contracts. These exclude any extra charges and are not a final stay total.</p><div className="ht-table-scroll"><table><thead><tr><th>Room / guests</th><th>Plan / dates</th><th>Listed amount</th><th>Source</th></tr></thead><tbody>{sourceRates(detail.hotel,selectedRoom).map(r=><tr key={r.contractId+r.id}><td>{r.room}<small>{r.occupancy} adults</small></td><td>{r.plan}<small>{display(r.from)} — {display(r.to)}</small></td><td><b>{currency(r.amount,r.currency)}</b><small>{r.unitConfirmed?'Per room':'Charging unit unconfirmed'} · {r.nightlyConfirmed?'per night':'nightly basis unconfirmed'}</small></td><td>{r.contractName}<small>Page {r.page} · {r.reviewed?'Checked':'Needs checking'}</small><details><summary>Source text</summary>{r.source}</details></td></tr>)}</tbody></table></div>{!sourceRates(detail.hotel,selectedRoom).length&&<p>0 · No direct room rate listed for these dates, guests and meal plan.</p>}</section>{detail.quote.issues.map((s,i)=><p className="ht-question" key={i}><AlertCircle size={16}/>{s}</p>)}{detail.quote.lines.length>0&&<details><summary>Nightly breakdown {detail.quote.complete?'':'· incomplete'}</summary><div className="ht-table-scroll"><table><thead><tr><th>Night</th><th>Room</th><th>Item</th><th>Amount</th><th>Source</th></tr></thead><tbody>{detail.quote.lines.map((l,i)=><tr key={i}><td>{l.date}</td><td>{l.room}</td><td>{l.label}</td><td>{currency(l.amount,detail.quote.currency)}</td><td>Page {l.page}</td></tr>)}</tbody></table></div></details>}</>}
 {detailTab==='Meals'&&<><h3>Separate meal prices</h3><p className="ht-hint">Use the listed scope and unit. These are not automatic room-plan conversions.</p>{data.contracts.filter(c=>c.hotelId===detail.hotel.id&&c.status!=='Archived').map(c=><div key={c.id} className="ht-rate"><h4>{c.name}</h4>{c.meals.length?<div className="ht-table-scroll"><table><thead><tr><th>Meal</th><th>Adult</th><th>Child</th><th>Unit / conditions</th></tr></thead><tbody>{c.meals.map(m=><tr key={m.id}><td>{m.label}</td><td>{m.adult===null?'0 · Not provided':currency(m.adult,c.currency)}</td><td>{m.child===null?'0 · Not provided':currency(m.child,c.currency)}</td><td>{m.unit||'Unit not confirmed'}<small>{m.note}</small></td></tr>)}</tbody></table></div>:<p>0 · Meal prices not provided</p>}</div>)}</>}
 {detailTab==='Policies'&&data.contracts.filter(c=>c.hotelId===detail.hotel.id&&c.status!=='Archived').map(c=><section key={c.id} className="ht-rate"><h3>{c.name}</h3><pre className="ht-policy-text">{c.notes||'Policies not entered yet.'}</pre>{c.issues.filter(i=>!i.resolution).map(i=><p className="ht-question" key={i.id}>{i.text}</p>)}</section>)}
 {detailTab==='Contract'&&data.contracts.filter(c=>c.hotelId===detail.hotel.id).map(c=><div className="ht-contract-link" key={c.id}><div><b>{c.name}</b><p>{c.status==='Draft'?'Needs checking':c.status} · {c.rates.length} rates</p></div><button className="ht-outline" onClick={()=>{setDetail(null);void openReview(c.id)}}>Review<ArrowUpRight size={15}/></button><a className="ht-outline" href={'/api/hotels/contract/'+c.id+'/file'} target="_blank" rel="noreferrer">Original<ArrowUpRight size={15}/></a></div>)}
 </div><div className="ht-add-stay"><label>Add to proposal<select value={proposalId} onChange={e=>setProposalId(e.target.value)}><option value="">Create a new proposal</option>{proposals.map(p=><option key={p.id} value={p.id}>{p.title}{p.client?' · '+p.client:''}</option>)}</select></label><button className="ht-primary" disabled={!criteria||adding} onClick={()=>void addStay(!detail.quote.complete)}>{adding?<LoaderCircle className="spin" size={17}/>:<Plus size={17}/>} {detail.quote.complete?'Add stay and cost':'Add hotel without price'}</button></div></div></div>}
 {confirmAction&&<div className="ht-overlay ht-confirm-overlay"><div className="ht-dialog ht-upload-dialog" role="dialog" aria-modal="true" aria-label={confirmAction==='close'?'Discard hotel changes':'Remove draft rate'}><div className="ht-dialog-head"><h2>{confirmAction==='close'?'Discard changes?':'Remove this rate?'}</h2><button className="ht-icon" aria-label="Keep editing" onClick={()=>setConfirmAction(null)}><X/></button></div><div className="ht-dialog-scroll"><p>{confirmAction==='close'?'Your changes have not been saved.':'This removes the rate from your draft. The original contract stays unchanged.'}</p></div><div className="ht-dialog-foot"><button className="ht-outline" onClick={()=>setConfirmAction(null)}>Keep editing</button><button className="ht-primary" onClick={()=>{if(confirmAction==='close')discardReview();else{if(draft)patch('rates',draft.rates.filter(r=>r.id!==confirmAction));setConfirmAction(null)}}}>{confirmAction==='close'?'Discard changes':'Remove rate'}</button></div></div></div>}
 </div>;
}
function Counter({label,value,min,max,change}:{label:string;value:number;min:number;max:number;change:(n:number)=>void}){return <div className="ht-counter"><b>{label}</b><div><button aria-label={'Remove '+label.toLowerCase()} disabled={value<=min} onClick={()=>change(value-1)}><Minus size={17}/></button><span>{value}</span><button aria-label={'Add '+label.toLowerCase()} disabled={value>=max} onClick={()=>change(value+1)}><Plus size={17}/></button></div></div>}
function Calendar({year,month,from,to,onSelect}:{year:number;month:number;from:string;to:string;onSelect:(s:string)=>void}){const first=new Date(year,month,1),days=new Date(year,month+1,0).getDate(),offset=(first.getDay()+6)%7;return <div className="ht-calendar"><h3>{first.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</h3><div className="ht-calendar-grid">{['Mo','Tu','We','Th','Fr','Sa','Su'].map(w=><span key={w}>{w}</span>)}{Array.from({length:offset},(_,i)=><i key={'b'+i}/>)}{Array.from({length:days},(_,i)=>{const s=`${year}-${String(month+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`;return <button key={s} aria-label={new Date(s+'T12:00:00').toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'})} className={s===from||s===to?'chosen':s>from&&s<to?'in-range':''} onClick={()=>onSelect(s)}>{i+1}</button>})}</div></div>}
function Amount({value,change,signed=false}:{value:number|null;change:(n:number|null)=>void;signed?:boolean}){const [text,setText]=useState(value===null?'':String(value)),[active,setActive]=useState(false);useEffect(()=>{if(!active)setText(value===null?'':String(value))},[value,active]);return <input type="text" inputMode="decimal" value={text} placeholder="Not provided" onFocus={()=>setActive(true)} onChange={e=>{const s=e.target.value;setText(s);const valid=!s.trim()||/^-?\d+(\.\d{0,2})?$/.test(s)&&Number.isFinite(Number(s))&&(signed||Number(s)>=0);e.target.setCustomValidity(valid?'':'Enter a valid amount with up to two decimals.')}} onBlur={e=>{if(e.target.checkValidity()){change(text.trim()?Number(text):null);setActive(false)}}}/>}
